import net.minecraft.resources.ResourceLocation;
import net.minecraftforge.common.ForgeConfigSpec;

public class EpicColoniesConfigClient {
    public static final ForgeConfigSpec.Builder BUILDER = new ForgeConfigSpec.Builder();
    public static final ForgeConfigSpec SPEC;
    public static ForgeConfigSpec.ConfigValue<Boolean> USE_CITIZEN_SKIN_DETECTION;
    public static ForgeConfigSpec.ConfigValue<Boolean> HIDE_CITIZEN_HELMET;
    public static ForgeConfigSpec.ConfigValue<Boolean> JOB_ONLY_ARMOR;
    public static ForgeConfigSpec.ConfigValue<List<? extends String>> VISIBLE_ARMOR_JOBS;
    public static ForgeConfigSpec.ConfigValue<Double> JOG_PLAYBACK_SPEED_MIN;
    public static ForgeConfigSpec.ConfigValue<Double> JOG_PLAYBACK_SPEED_MAX;
    private static List<ResourceLocation> defaultArmorJobsLoc;
    private static List<String> defaultArmorJobs;

    static {
        defaultArmorJobsLoc = new ArrayList<ResourceLocation>();
        defaultArmorJobs = new ArrayList<String>();
        defaultArmorJobsLoc.add(ModJobs.KNIGHT_ID);
        defaultArmorJobsLoc.add(ModJobs.KNIGHT_TRAINING_ID);
        defaultArmorJobsLoc.add(ModJobs.ARCHER_ID);
        defaultArmorJobsLoc.add(ModJobs.ARCHER_TRAINING_ID);
        for (ResourceLocation loc : defaultArmorJobsLoc) {
            defaultArmorJobs.add(loc.toString());
        }
        BUILDER.push("Cosmetic");
        USE_CITIZEN_SKIN_DETECTION = BUILDER.comment("Should Citizens Use The Skin Detection For Citizens With Lower Eye Textures (Such as some which are part of MineColonies 'Patreon Exclusive' Packs)").define("Use Citizen Skin Detection", true);
        HIDE_CITIZEN_HELMET = BUILDER.comment("Should Citizens With Visible Armor Have Their Helmet Hidden").define("Hide Citizen Helmet", false);
        JOB_ONLY_ARMOR = BUILDER.comment("Whether or not Armor Should Only Be Shown For Specific Citizen Jobs (Jobs Defined In Config Below)").define("Show Armor For Specific Jobs", true);
        VISIBLE_ARMOR_JOBS = BUILDER.comment("Which Citizen Jobs Should Have Visible Armor").defineList("Visible Armor Jobs", defaultArmorJobs, o -> o instanceof String);
        BUILDER.pop();
        BUILDER.push("Animations");
        JOG_PLAYBACK_SPEED_MIN = BUILDER.comment("The minimum speed of he citizen jog animation according to their current movement speed").defineInRange("Jog Animation Min Speed", 1.0, (double)0.01f, 10.0);
        JOG_PLAYBACK_SPEED_MAX = BUILDER.comment("The maximum speed of he citizen jog animation according to their current movement speed").defineInRange("Jog Animation Max Speed", 3.25, (double)0.01f, 10.0);
        SPEC = BUILDER.build();
    }
}

