import com.minecolonies.api.entity.ai.statemachine.states.IState;
import com.mojang.datafixers.util.Pair;
import yesman.epicfight.api.animation.LivingMotion;
import yesman.epicfight.api.animation.LivingMotions;
import yesman.epicfight.api.utils.ExtendableEnum;

public enum EpicColoniesLivingMotions implements LivingMotion
{
    JOG(null, null, false),
    USE(null, null, true),
    PLACE(null, null, true),
    DIG((IState)AIWorkerState.MINE_BLOCK, (LivingMotion)LivingMotions.DIGGING, true),
    SIT_SLEEP((IState)AIWorkerState.GUARD_SLEEP, null, false);

    private final IState citizenState;
    private final LivingMotion parentMotion;
    private final boolean isComposite;
    public final int id;

    private EpicColoniesLivingMotions(IState citizenState, LivingMotion parentMotion, boolean isComposite) {
        this.citizenState = citizenState;
        this.parentMotion = parentMotion;
        this.id = LivingMotion.ENUM_MANAGER.assign((ExtendableEnum)this);
        this.isComposite = isComposite;
    }

    public static Pair<LivingMotion, Boolean> getLivingMotionFromAiState(IState iState) {
        for (EpicColoniesLivingMotions livingMotion : EpicColoniesLivingMotions.values()) {
            if (livingMotion.citizenState == null || livingMotion.citizenState != iState) continue;
            if (livingMotion.parentMotion != null) {
                return new Pair((Object)livingMotion.parentMotion, (Object)livingMotion.isComposite);
            }
            return new Pair((Object)livingMotion, (Object)livingMotion.isComposite);
        }
        return null;
    }

    public int universalOrdinal() {
        return this.id;
    }
}

